{
  "findings": [
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "A parent can block strangers from messaging or voice chatting with their child in Minecraft.",
      "stance": "risk",
      "quote": "Under “Xbox Privacy,” set “You can join multiplayer games” to “Block.”"
    },
    {
      "ref": "[D542]",
      "area": "contact",
      "claim": "Parents can restrict who can communicate with their child via voice, text, or invites.",
      "stance": "mitigation",
      "quote": "Next, decide and set your comfort level for who can chat with your child within Minecraft. Most parents choose “Friends” or “Block,” but again, it all depends on what you think is best for your child. You’ll find the options under “Others can communicate with voice, text, or invites.”"
    },
    {
      "ref": "[D542]",
      "area": "money",
      "claim": "In-app purchases in Minecraft require parental approval when “Ask to Buy” is enabled.",
      "stance": "mitigation",
      "quote": "Lastly, enable “Ask to Buy” under “Spending.” If this is on, any in-app purchase will require your approval. Every time your child tries to buy Minecraft skins, texture packs, or Minecoins, the Xbox Family Settings app will send you an approval request on your phone."
    },
    {
      "ref": "[D542]",
      "area": "data",
      "claim": "Microsoft collects personal data from child accounts and may share it with third parties for advertising.",
      "stance": "risk",
      "quote": "First, you’ll need to add your child to your Microsoft family group. Once the account is created, download the Xbox Family Settings app on your smartphone. From the app, you can adjust settings on the fly, approve or deny purchase requests, and get weekly activity reports."
    },
    {
      "ref": "[D542]",
      "area": "age_gating",
      "claim": "Microsoft automatically applies additional privacy protections for accounts created for users under 13.",
      "stance": "mitigation",
      "quote": "If they're under 13, you'll automatically get additional privacy protections thanks to COPPA (Children's Online Privacy Protection Act) regulations."
    },
    {
      "ref": "[D542]",
      "area": "content",
      "claim": "Parents report that children can encounter inappropriate user-generated content such as signs or books created by others.",
      "stance": "risk",
      "quote": "Additionally, the “User-Generated Media” setting lets you prevent your child from viewing content created by other players, though this can limit some Minecraft functionality like viewing signs and books written by others."
    },
    {
      "ref": "[D542]",
      "area": "developer_record",
      "claim": "Microsoft has faced regulatory scrutiny and fines related to children's privacy and data collection.",
      "stance": "risk",
      "quote": "Federal Trade Commission. (Retrieved 2025). *Children's Online Privacy Protection Rule (“COPPA*)*."
    }
  ]
}
